package android.app.appfunctions; import java.util.concurrent.Executor; import android.os.OutcomeReceiver; public class AppFunctionManager { public static final AppFunctionManager INSTANCE=new AppFunctionManager(); public static int dispatches; public static OutcomeReceiver<Object,Throwable> original; public void isAppFunctionEnabled(String f,String p,Executor e,OutcomeReceiver<Object,Throwable> c){if(!"com.oculus.vrshell".equals(p)||!"com.oculus.vrshell.appfunctions.ShellAppFunctions#recenterView".equals(f))throw new SecurityException();e.execute(()->c.onResult(true));} public void executeAppFunction(ExecuteAppFunctionRequest r,Executor e,android.os.CancellationSignal s,OutcomeReceiver<Object,Throwable> c){dispatches++;original=new OutcomeReceiver<Object,Throwable>(){public void onResult(Object v){e.execute(()->c.onResult(v));} public void onError(Throwable t){e.execute(()->c.onError(t));}};} }
